248:  * Estimate encounter quality from the richness of the player response.
249:  * Quality reflects engagement depth: diverse drive signals, shadow surfacing,
250:  * and narrative richness indicate higher engagement.
251:  */
252: function estimateResponseQuality(response: PlayerResponse): number {
253:   let quality = 0.5; // baseline for any completed encounter
254: 
255:   // Diverse drive directionality boosts quality
256:   const driveValues = Object.values(response.driveDirectionality);
257:   const uniqueDrives = new Set(driveValues).size;
258:   if (uniqueDrives >= 3) quality += 0.15;
259:   else if (uniqueDrives >= 2) quality += 0.08;
260: 
261:   // Shadow surfacing indicates deep engagement
262:   if (response.shadowSurfaced !== null) quality += 0.15;
263: 
264:   // Shadow resolution indicates integration
265:   if (response.shadowResolvedId !== null) quality += 0.1;
266: 
267:   // Longer narrative suggests deeper engagement
268:   if (response.narrativeSummary.length > 100) quality += 0.1;
269:   else if (response.narrativeSummary.length > 50) quality += 0.05;
270: 
271:   return Math.min(1.0, quality);
272: }
