301:   const bleedThrough = detectBleedThrough(updatedSig.theta.lastEncounter, now);
302: 
303:   const scheduled = scheduleNext(updatedSig, updatedWorld, session, now, 1, undefined, bleedThrough);
304:   const encounter = scheduled[0] ?? null;
305: 
306:   // 4. Check transformation threshold
307:   const transformation = detectThreshold(updatedSig);
308: 
309:   return { encounter, encounters: scheduled, sig: updatedSig, world: updatedWorld, transformation, bleedThrough };
310: }
311: 
