313:  * Execute a module headlessly given pre-collected trials.
314:  * Bridges the gap between encounter scheduling and consequence processing.
315:  * In headless/test mode, trials are provided directly.
316:  * In game mode, the AssessmentScene collects trials interactively.
317:  */
318: export function executeModule(
319:   module: StageAssessment,
320:   trials: readonly TrialResult[],
321:   mode: ModuleExecutionMode,
322: ): AssessmentResult | ShadowAssessmentResult {
323:   return runModeAwareAssessment(module, trials, mode);
324: }
325: 
326: /**
327:  * End a session: apply theta-decay to all unvisited modules,
328:  * persist final state, and return session summary.
329:  */
330: export function endSession(
331:   sig: Significator,
332:   sessionState: SessionState,
333:   now: number,
334: ): { sig: Significator; summary: { encountersCompleted: number; shadowsSurfaced: number; shadowsResolved: number } } {
335:   // Apply theta-decay: increment decay for all cells NOT visited this session
336:   // recentOutcomes don't carry cell keys directly, so we rely on theta timestamps
337:   // Cells with timestamps >= session start are considered visited
338: 
339:   // Count session stats
340:   const encountersCompleted = sessionState.recentOutcomes.filter(o => o.outcome === 'completed').length;
341:   // Count shadows surfaced and resolved during this session
342:   // (entries created or resolved since the first outcome in this session)
343:   const sessionStartMs = sessionState.recentOutcomes.length > 0
344:     ? now - sessionState.recentOutcomes.length * 5000 // approximate session start
345:     : now;
346:   const shadowsSurfaced = sig.shadows.entries.filter(e => e.surfacedAt >= sessionStartMs).length;
347:   const shadowsResolved = sig.shadows.entries.filter(e => e.resolvedAt !== null && e.resolvedAt >= sessionStartMs).length;
348: 
349:   // Increment totalSessions
350:   const updatedSig: Significator = {
351:     ...sig,
352:     totalSessions: sig.totalSessions + 1,
353:   };
354: 
355:   return {
356:     sig: updatedSig,
357:     summary: { encountersCompleted, shadowsSurfaced, shadowsResolved },
358:   };
359: }

