256:   /**
257:    * Build a narrative continuity context from the last 3 encounters.
258:    * Injected into both LLM system prompt and fallback task framing.
259:    */
260:   private buildContinuityContext(): string {
261:     if (this.history.length === 0) return '';
262:     const recent = this.history.slice(-3);
263:     const lines = recent.map((r, i) => {
264:       const passed = Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced');
265:       const shadow = r.shadowSurfaced ? ` Shadow surfaced: ${r.shadowSurfaced}.` : '';
266:       const altShift = r.altitudeShift ? ` LINE ADVANCED: ${r.altitudeShift.line} ${r.altitudeShift.from}→${r.altitudeShift.to}.` : '';
267:       const polarity = r.polarityTrace.energeticDirection === 'Radiative' ? ' (STO/radiative)' : r.polarityTrace.energeticDirection === 'Absorptive' ? ' (STS/absorptive)' : '';
268:       const moduleRef = r.encounterId.split(':')[0] ?? '';
269:       return `  ${i + 1}. [${moduleRef}] ${passed ? '✓ PASSED' : '✗ FAILED'}${polarity} — ${r.narrativeSummary.slice(0, 150)}${shadow}${altShift}`;
270:     });
271:     return `\n[RECENT JOURNEY — the player's developmental arc. Build upon these encounters. Reference specific events from them. The player remembers what happened.]\n${lines.join('\n')}`;
272:   }
