274:   /**
275:    * Build a brief history prefix for fallback task framing.
276:    * Now includes specific encounter details for narrative continuity.
277:    */
278:   private buildBriefHistory(): string {
279:     if (this.history.length === 0) return '';
280:     const last3 = this.history.slice(-3);
281:     const parts: string[] = [`You have faced ${this.history.length} challenges before.`];
282:     for (const r of last3) {
283:       const passed = Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced');
284:       const shadow = r.shadowSurfaced ? ` A ${r.shadowSurfaced} pattern surfaced.` : '';
285:       parts.push(passed
286:         ? `Recently: ${r.narrativeSummary.slice(0, 100)}...${shadow}`
287:         : `Recently: ${r.narrativeSummary.slice(0, 100)}...${shadow}`);
288:     }
289:     return parts.join(' ') + ' Now: ';
290:   }
