292:   public async run(): Promise<OrchestratorResult> {
293:     const [line, stage] = this.encounter.moduleRef.split(':') as [Line, Stage];
294:     const now = Date.now();
295: 
296:     // If noLlm flag is set, skip LLM entirely and go directly to fallback
297:     if (this.noLlm) {
298:       return this.runFallback(line, stage, now);
299:     }
300: 
301:     // G.2: Language-Reflective modality gets a special LLM-driven assessment path
302:     // This produces genuine open-ended dialogue scoring instead of MCQ wrapping
303:     if (this.encounter.modality === 'LanguageReflective') {
304:       return this.runLanguageReflective(line, stage, now);
305:     }
306: 
307:     // 1. Build context system prompt
308:     const continuityContext = this.buildContinuityContext();
309:     const contextInput = {
310:       encounter: this.encounter,
311:       significator: this.significator,
312:       holonRegistry: { holons: this.world.holons },
313:       conceptIndex: this.conceptIndex,
314:       recentConsequences: this.history,
315:       sessionContext: { energy: 'high' as const },
316:     };
317:     const context = buildContext(contextInput);
318: 
319:     // Build assessment module context for the LLM
320:     const assessmentContext = this.module ? this.buildAssessmentContext(this.module) : '';
321: 
322:     let shadowContext = '';
323:     if (this.encounter.executionMode === 'shadow') {
324:       const [shadowLine, shadowStage] = this.encounter.moduleRef.split(':') as [Line, Stage];
325:       const { generateShadowContent, buildShadowPromptSuffix } = await import('../engines/ShadowContentGenerator.js');
326:       const shadowContent = generateShadowContent(shadowLine, shadowStage, this.encounter.shadowTarget);
327:       
328:       const unresolvedShadows = this.significator.shadows.entries.filter(
329:         (e: { line: string; resolvedAt: number | null }) => e.line === shadowLine && e.resolvedAt === null
330:       ).length;
331:       
332:       shadowContext = buildShadowPromptSuffix(shadowContent, shadowLine, shadowStage, unresolvedShadows);
333:     }
334: 
335:     const systemPrompt = `${context.systemPrompt}${assessmentContext}${continuityContext}${shadowContext}
336: [AGENT RULES]
337: 1. You are the Agentic Game Master driving this developmental encounter.
338: 2. Present the encounter situationally and narratively. If you need to present stimuli, choices, or ask questions, ALWAYS call the 'ask_user_question' tool. Do not ask questions in raw text responses.
339: 3. Every ask_user_question call MUST include exactly 4 MCQ options AND set allowWriteIn=true for a 5th manual write-in option. Label the write-in option clearly (e.g., "Other (describe in your own words)").
340: 4. Keep the flow interactive, building upon prior answers.
341: 5. This encounter has a budget of 2 exchanges. After the player has responded to 2 questions, you MUST call 'complete_encounter'. Do NOT generate more than 2 ask_user_question calls.
342: 6. When calling 'complete_encounter', evaluate the player per the DRIVE PROBES section. Score each drive independently. Provide driveScores (0.0-1.0 per drive) and driveSignals (pathology enum per drive).
343: 7. If RECENT ENCOUNTERS are listed, reference them subtly — the player's journey has continuity.`;
344: 
345:     if (this.messages.length === 0) {
346:       this.messages.push({
347:         role: 'user',
348:         content: `Start the encounter: ${this.encounter.id} (${line} - ${stage}). Introduce the scene and ask the first question.`
349:       });
350:     }
351: 
352:     let loopCount = 0;
353:     const maxLoops = 10; // Safety guard
354:     let askCount = 0; // Track ask_user_question calls for budget enforcement
355: 
356:     while (loopCount < maxLoops) {
357:       loopCount++;
358: 
359:       // Request next turn from LLM
360:       const res = await queryLLMWithTools(systemPrompt, this.messages, TOOLS);
361: 
362:       // Detect LLM unavailability on first call — switch to fallback
363:       if (loopCount === 1 && res.content && res.content.trim().startsWith('{"error"') && (!res.toolCalls || res.toolCalls.length === 0)) {
364:         return this.runFallback(line, stage, now);
365:       }
366: 
367:       const assistantMsg: AgentMessage = {
368:         role: 'assistant',
369:         content: res.content,
370:         toolCalls: res.toolCalls,
371:       };
372:       this.messages.push(assistantMsg);
373: 
374:       if (res.toolCalls && res.toolCalls.length > 0) {
375:         // Execute tool calls
376:         for (const tc of res.toolCalls) {
377:           if (tc.function.name === 'ask_user_question') {
378:             askCount++;
379:             const params = JSON.parse(tc.function.arguments) as AskUserQuestionParams;
380:             
381:             // Present to UI (Phaser or CLI)
382:             const result = await this.uiHandler.askUser(params);
383: 
384:             // Record tool response
385:             this.messages.push({
386:               role: 'tool',
387:               content: JSON.stringify(result),
388:               toolCallId: tc.id,
389:               name: 'ask_user_question'
390:             });
391: 
392:             // Budget enforcement: after 2 exchanges, force complete_encounter
393:             if (askCount >= 2 && !res.toolCalls.some(t => t.function.name === 'complete_encounter')) {
394:               this.messages.push({
395:                 role: 'user',
396:                 content: 'The encounter budget of 2 exchanges is exhausted. You MUST now call complete_encounter with your evaluation of the player. Do NOT ask another question.'
397:               });
398:             }
399:           } else if (tc.function.name === 'complete_encounter') {
400:             const params = JSON.parse(tc.function.arguments) as {
401:               passed: boolean;
402:               scores?: Partial<Record<MeasureDimension, number>>;
403:               driveScores: { agency: number; communion: number; eros: number; agape: number };
404:               driveSignals: { agency: string; communion: string; eros: string; agape: string };
405:               feedback: string;
406:               polarityDirection: 'sto' | 'sts' | 'neutral';
407:               shadowSignal?: {
408:                 quadrant: ShadowQuadrant;
409:                 intensity: number;
410:               };
411:               narrativeSummary: string;
412:             };
413: 
414:             // G.24: Clamp LLM-provided drive scores to [0, 1]
415:             const clamp = (v: number) => Math.max(0, Math.min(1, v));
416:             const safeDriveScores = {
417:               agency: clamp(params.driveScores.agency),
418:               communion: clamp(params.driveScores.communion),
419:               eros: clamp(params.driveScores.eros),
420:               agape: clamp(params.driveScores.agape),
421:             };
422: 
423:             const finalResult = this.createAssessmentResult(params.passed, params.scores || {}, safeDriveScores);
424:             const outcome = this.finalizeEncounter(params, now);
425: 
426:             return {
427:               ...outcome,
428:               finalResult,
429:               messages: this.messages,
430:             };
431:           }
432:         }
433:       } else {
434:         // Fallback: If assistant didn't call any tools, prompt it to proceed
435:         this.messages.push({
436:           role: 'user',
437:           content: 'Continue with the encounter. If the encounter is complete, call complete_encounter. Otherwise, call ask_user_question.'
438:         });
439:       }
440:     }
441: 
442:     // Safety fallback termination if we loop too many times
443:     const fallbackParams = {
444:       passed: true,
445:       feedback: 'Encounter completed via timeout.',
446:       polarityDirection: 'neutral' as const,
447:       narrativeSummary: `The player successfully navigated the challenge of ${this.encounter.moduleRef}.`,
448:     };
449:     const finalResult = this.createAssessmentResult(true, {});
450:     const outcome = this.finalizeEncounter(fallbackParams, now);
451: 
452:     return {
453:       ...outcome,
454:       finalResult,
455:       messages: this.messages,
456:     };
457:   }
