606:   /**
607:    * Fallback mode: use module content when available, FallbackProvider otherwise.
608:    * When a module is available, presents real assessment tasks (n-back, dilemmas,
609:    * emotion identification, etc.) as narrative challenges and evaluates responses
610:    * using the module's drive probes. Also detects shadow patterns and computes
611:    * altitude shifts from consistent healthy patterns.
612:    */
613:   private async runFallback(line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
614:     // CHECK: If we have an assessment module, use it for a real assessment
615:     if (this.module) {
616:       return this.runModuleAssessment(line, stage, now);
617:     }
618: 
619:     // Original generic fallback when no module is available
620:     const fallback = getFallback(this.encounter.modality, line, stage);
621:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
622:     const holonName = holon?.name ?? 'A presence';
