634:         options = [
635:           { label: 'Reflect deeply', description: 'Consider the question from multiple angles' },
636:           { label: 'Respond instinctively', description: 'Trust your first impulse' },
637:           { label: 'Sit with it', description: 'Allow the question to remain open' },
638:           { label: 'Challenge the premise', description: 'Question the foundation of what was asked' },
639:         ];
640:         break;
641:       case 'ScenarioChoice':
642:         narrativeIntro = `${holonName} confronts you. The air is tense. A choice must be made.`;
643:         questionText = fallback.scenario ?? 'A crossroads appears. Each path carries weight.';
644:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
645:         break;
646:       case 'Strategic':
647:         narrativeIntro = `The war-table is spread before you. ${holonName} surveys the terrain. Three routes. Limited forces.`;
648:         questionText = fallback.scenario ?? fallback.prompt ?? 'Resources are limited. The map shows three routes to the objective.';
649:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
650:         break;
651:       case 'Embodied':
652:         narrativeIntro = `The war-drums begin. ${holonName} guides you. Your body knows this rhythm.`;
653:         questionText = fallback.prompt ?? 'Close your eyes. Where do you feel tension in your body right now?';
654:         options = [
655:           { label: 'Follow the rhythm', description: 'Let the drum guide your body' },
656:           { label: 'Resist the beat', description: 'Fight against the pull' },
657:           { label: 'Breathe into it', description: 'Allow the sensation to move through you' },
658:           { label: 'Still yourself', description: 'Find the stillness within the movement' },
659:         ];
660:         break;
661:       case 'SocialCooperative':
662:         narrativeIntro = `${holonName} looks to you. Others wait for direction. The group needs your word.`;
663:         questionText = fallback.scenario ?? 'The scouts look to you. The path splits — one leads through danger, the other through uncertainty.';
664:         options = (fallback.options ?? []).map(o => ({ label: o.text, description: o.text }));
665:         break;
666:       case 'ImmersiveRPG':
667:         narrativeIntro = `The world stretches before you. ${holonName} appears — ${holonRole} of this domain. What calls?`;
668:         questionText = fallback.prompt ?? 'The world stretches before you. A path winds through unfamiliar terrain. Something waits ahead.';
669:         options = [
670:           { label: 'Press forward', description: 'Step into the unknown' },
671:           { label: 'Survey the area', description: 'Gather information first' },
672:           { label: 'Seek shelter', description: 'Find safety before advancing' },
673:           { label: 'Call out', description: 'Announce your presence' },
674:         ];
675:         break;
676:       default:
677:         narrativeIntro = `${holonName} presents a challenge. The moment demands clarity.`;
