737:   /**
738:    * Module-aware fallback: uses the assessment module's tasks, drive probes,
739:    * and scoring rubric to present a real developmental assessment even without the LLM.
740:    * Selects a task matching the encounter modality, presents it as a narrative challenge,
741:    * evaluates the response against drive probes, detects shadow patterns,
742:    * and computes altitude progression.
743:    */
744:   private async runModuleAssessment(_line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
745:     const module = this.module!;
746:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
747:     const holonName = holon?.name ?? 'A presence';
748:     const currentModality = this.encounter.modality;
749: 
750:     // 1. Select the best task from the module based on modality
751:     const task = this.selectTaskForModality(module, currentModality);
752:     // Track the actual presented task for narrative building (fix B.2)
753:     this._currentPresentedTask = task;
754: 
755:     // 2. Present the task as a narrative challenge via uiHandler
756:     const askResult = await this.presentModuleTask(module, task, currentModality, holonName);
757:     const answer = askResult.answers[0];
758:     const rawLabel = answer?.selectedLabels[0] ?? '';
759:     const writeIn = answer?.writeInValue;
760:     const playerResponseText = writeIn ?? rawLabel;
761: 
762:     // 3. Evaluate using the TaskRenderer's evaluate() if available (produces TrialResult with timing/accuracy)
763:     //    Fall back to drive-probe evaluation if no renderer evaluate is available
764:     const endTimeMs = Date.now();
765:     let evaluation: {
766:       passed: boolean;
767:       polarityDirection: 'sto' | 'sts' | 'neutral';
768:       driveScores: { agency: number; communion: number; eros: number; agape: number };
769:       driveSignals: { agency: string; communion: string; eros: string; agape: string };
770:       feedback: string;
771:     };
772:     let trialResult: TrialResult | null = null;
773: 
774:     if (this._currentRendererEvaluate) {
775:       // Use the TaskRenderer's evaluate function for real scoring
776:       trialResult = this._currentRendererEvaluate(playerResponseText, this._currentTaskStartTime, endTimeMs);
777: 
778:       // Extract drive metadata from the trial's rawResponse (set by TaskRenderers)
779:       const rawResp = trialResult?.rawResponse as any;
780:       const matchedDrive: string | null = rawResp?.matchedDrive ?? null;
781:       const matchedPolarity: string = rawResp?.matchedPolarity ?? 'neutral';
782:       const correctnessScore: number = rawResp?.correctnessScore ?? 0.5;
783: 
784:       // Use correctnessScore as the primary scoring signal (from TaskRenderer options)
785:       const baseScore = Math.min(1, Math.max(0, correctnessScore));
786: 
787:       // D.9: Use shared shadow keyword detection helper (DRY)
788:       let writeInDriveDetection: { drive: string; polarity: string; shadowKeyword: string | null } | null = null;
789:       if (writeIn) {
790:         writeInDriveDetection = AgenticOrchestrator.detectWriteInShadow(writeIn);
791:       }
792: 
793:       // When a write-in is present, its keyword-based detection takes priority over
794:       // the renderer's label matching (which can false-positive on short words like 'I').
795:       const effectiveDrive = writeInDriveDetection?.drive ?? matchedDrive ?? null;
796:       const effectivePolarity = writeInDriveDetection?.polarity ?? (matchedPolarity !== 'neutral' ? matchedPolarity : 'neutral');
797: 
798:       // Build differentiated drive scores:
799:       // - The matched/driven drive gets the full baseScore (or boosted for write-in depth)
800:       // - Other drives get baseline neutral (0.5)
801:       // - For write-ins with no shadow detection, apply a depth boost and distribute evenly
802:       const isWriteInWithNoShadow = matchedDrive === null && !writeInDriveDetection && !!writeIn;
803: 
804:       // ── SCORING FIX: Use rubric dimension weights on TrialResult dimensions ──
805:       // OLD: averaged 4 drives → compressed to ~0.55 always, even correct answers failed at threshold 0.6
806:       // NEW: compute weighted score from TrialResult dimensions using the module's rubric weights.
807:       // This gives a true performance signal: correct MCQ → ~0.8, partial → ~0.55, wrong → ~0.25.
808:       const rubricWeights = module.scoringRubric.dimensionWeights;
809:       const trialDims = trialResult!.dimensions;
810:       let weightedSum = 0;
811:       let totalWeight = 0;
812:       for (const [dim, weight] of Object.entries(rubricWeights)) {
813:         const val = trialDims[dim as keyof typeof trialDims];
814:         if (weight && typeof val === 'number') {
815:           weightedSum += val * weight;
816:           totalWeight += weight;
817:         }
818:       }
819:       // Blend the rubric-weighted score with the drive-correctness score for a robust signal
820:       const rubricScore = totalWeight > 0 ? weightedSum / totalWeight : baseScore;
821:       const blendedScore = rubricScore * 0.6 + baseScore * 0.4;
822: 
823:       // Drive scores: matched drive gets blendedScore (consistent with pass/fail),
824:       // write-in depth bonus applied on top. Unmatched drives get a lower baseline.
825:       const matchedScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
826:       const driveScores = {
827:         agency: effectiveDrive === 'agency' ? matchedScore
828:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
829:           : matchedScore,
830:         communion: effectiveDrive === 'communion' ? matchedScore
831:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
832:           : matchedScore,
833:         eros: effectiveDrive === 'eros' ? matchedScore
834:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
835:           : matchedScore,
836:         agape: effectiveDrive === 'agape' ? matchedScore
837:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
838:           : matchedScore,
839:       };
840: 
841:       // Determine polarity from the effective drive detection
842:       const polarityDirection = effectivePolarity === 'sts' ? 'sts' as const
843:         : effectivePolarity === 'sto' ? 'sto' as const
844:         : 'neutral' as const;
845: 
846:       // Derive drive signals from the expression pattern.
847:       // IMPORTANT: Shadow signals ONLY come from write-in keyword detection or forceShadow.
848:       // A wrong MCQ answer (low correctnessScore) is a performance miss, NOT a shadow expression.
849:       const shadowFromWriteIn = writeInDriveDetection?.shadowKeyword ?? null;
850:       const driveSignals = {
851:         agency: effectiveDrive === 'agency'
852:           ? (shadowFromWriteIn === 'DarkAddicted' ? 'DarkAddicted' : 'HealthyBalanced')
853:           : 'HealthyBalanced',
854:         communion: effectiveDrive === 'communion'
855:           ? (shadowFromWriteIn === 'DarkAverted' ? 'DarkAverted' : 'HealthyBalanced')
856:           : 'HealthyBalanced',
857:         eros: effectiveDrive === 'eros'
858:           ? (shadowFromWriteIn === 'GoldenAddicted' ? 'GoldenAddicted' : 'HealthyBalanced')
859:           : 'HealthyBalanced',
860:         agape: effectiveDrive === 'agape'
861:           ? (shadowFromWriteIn === 'GoldenAverted' ? 'GoldenAverted' : 'HealthyBalanced')
862:           : 'HealthyBalanced',
863:       };
864: 
865:       // Determine pass: blendedScore must meet threshold AND no shadow pathology
866:       const passThreshold = module.scoringRubric.passThreshold ?? 0.5;
867:       const effectiveScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
868:       const hasShadow = !!shadowFromWriteIn;
869:       const passed = !hasShadow && effectiveScore >= passThreshold;
870: 
871:       // Build contextual developmental feedback based on score, drive, polarity, and history
872:       const driveLabel = effectiveDrive ?? 'unidentified';
873:       const polarityLabel = effectivePolarity === 'sts' ? 'self-oriented' : effectivePolarity === 'sto' ? 'other-oriented' : 'balanced';
874:       const scorePct = (baseScore * 100).toFixed(0);
875:       const historyCount = this.history.length;
876:       const recentPasses = this.history.slice(-3).filter(r => Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced')).length;
877:       const consistencyNote = recentPasses >= 3 ? ' You are building strong momentum across encounters.'
878:         : recentPasses === 0 && historyCount >= 2 ? ' The last few encounters have been challenging — this is where real growth happens.'
879:         : '';
880: 
881:       const feedback = hasShadow
882:         ? `A ${shadowFromWriteIn} pattern surfaced through your ${driveLabel} expression (${polarityLabel}). In the developmental framework, this shadow arises when the ${driveLabel} drive becomes imbalanced — either clinging to lower patterns (dark) or bypassing toward higher without integration (golden). Naming it here is the first step toward healing it. ${historyCount > 0 ? `This is your ${historyCount + 1}th encounter — each shadow surfaced is an opportunity for the field to work with you.` : ''}`
883:         : passed
884:           ? `Your ${driveLabel} drive expressed with health (performance: ${scorePct}%, polarity: ${polarityLabel}). ${parseInt(scorePct) >= 80 ? 'Strong performance — the integration is deepening across the ' + module.line.toLowerCase() + ' dimension.' : 'Solid engagement — the ' + module.line.toLowerCase() + ' capacity at ' + module.stage + ' stage is growing.'} ${consistencyNote}The field recognizes your sustained attention to this developmental edge.`
885:           : `Your ${driveLabel} drive expressed at ${scorePct}% performance (${polarityLabel}). ${parseInt(scorePct) >= 40 ? 'Close to the threshold — the gap between where you are and where this capacity can be is narrowing. A focused effort on the next encounter may tip the balance.' : 'This is a genuine edge for you. The ' + module.line.toLowerCase() + ' line at ' + module.stage + ' stage is where your developmental work lives right now — not as punishment, but as invitation.'} The ${module.line.toLowerCase()} dimension will continue to offer opportunities to strengthen this capacity.`;
886: 
887:       evaluation = {
888:         passed,
889:         polarityDirection,
890:         driveScores,
891:         driveSignals,
892:         feedback,
893:       };
894:     } else {
895:       // Fallback: keyword-based evaluation
896:       evaluation = this.evaluateViaDriveProbes(module, playerResponseText);
897:     }
898: 
899:     // 4. Detect shadow surfacing from response pattern (with optional forceShadow override)
900:     const validQuadrants = ['DarkAddiction', 'DarkAllergy', 'GoldenAddiction', 'GoldenAllergy'] as const;
901:     const forcedQuadrant = this.forceShadow && validQuadrants.includes(this.forceShadow as any)
902:       ? this.forceShadow as ShadowQuadrant
903:       : null;
904:     // Shadow detection only fires for write-in text (free-form responses)
905:     // MCQ option labels should NOT trigger shadow detection — they're structured choices, not expressions.
906:     const isWriteIn = !!writeIn;
