375:  * and poor integration rate relative to surfacing.
376:  */
377: export function normaliseShadowTopology(input: ShadowTopologyInput): number {
378:   const countPenalty = Math.min(input.unresolvedCount / 12, 1.0);
379:   const severityPenalty = input.maxSeverity;
380:   const compoundPenalty = Math.min(input.compoundPatternCount / 4, 1.0);
381:   const stalePenalty = Math.min(input.oldestUnresolvedAge / 20, 1.0);
