383:   // Integration credit: ratio of integration to surfacing, capped at 1.0
384:   const integrationCredit = input.recentSurfacingRate > 0
385:     ? Math.min(input.integrationRate / input.recentSurfacingRate, 1.0)
386:     : 0;
