399: /**
400:  * Normalise transformation readiness dimension.
401:  * Active transformation saturates at 1.0. No target returns 0.0.
402:  * Otherwise: edgeProgress * clearanceFactor * saturation * recoveryDamping.
403:  */
404: export function normaliseTransformationReadiness(input: TransformationReadinessInput): number {
405:   if (input.pendingTransformation) return 1.0;
406:   if (!input.targetStage) return 0.0;
407: 
408:   const edgeProgress = Math.min(input.linesAtEdge / 6, 1.0);
409:   const clearanceFactor = input.shadowClearance ? 1.0 : 0.6;
410:   const saturationFactor = input.catalystSaturation;
411: 
412:   // Post-transformation recovery: reduce readiness signal for 5 sessions
413:   const recoveryDamping = input.sessionsSinceLastTransformation < 5
414:     ? input.sessionsSinceLastTransformation / 5
415:     : 1.0;
416: 
417:   return clamp(edgeProgress * clearanceFactor * saturationFactor * recoveryDamping);
