421: // Weight adjustment
422: // ---------------------------------------------------------------------------
423: 
424: /**
425:  * Context-sensitive weight adjustment. Weights shift based on the
426:  * Significator's current developmental state to ensure proportional
427:  * response to the most urgent developmental need.
428:  */
429: export function adjustWeights(
430:   defaults: CCIWeights,
431:   inputs: CCIDimensionInputs,
432: ): CCIWeights {
433:   // Active transformation override: hardcoded weights for transformation mode
434:   if (inputs.transformationReadiness.pendingTransformation) {
435:     return {
436:       altitude: 0.05,
437:       driveHealth: 0.10,
438:       polarity: 0.05,
439:       shadowTopology: 0.10,
440:       transformationReadiness: 0.70,
441:     };
442:   }
443: 
444:   const adjusted = { ...defaults };
445: 
446:   // Near-transformation: boost TR, reduce altitude and polarity
447:   if (inputs.transformationReadiness.linesAtEdge >= 4) {
448:     adjusted.transformationReadiness += 0.10;
449:     adjusted.altitude -= 0.05;
450:     adjusted.polarity -= 0.05;
451:   }
452: 
453:   // Heavy shadow load: boost shadow, reduce transformation readiness
454:   if (inputs.shadowTopology.unresolvedCount > 8 || inputs.shadowTopology.maxSeverity > 0.7) {
455:     adjusted.shadowTopology += 0.10;
456:     adjusted.transformationReadiness -= 0.10;
457:   }
458: 
459:   // Severe drive imbalance: boost drive health, reduce polarity and altitude
460:   if (inputs.driveHealth.maxFixationRisk > 0.7) {
461:     adjusted.driveHealth += 0.10;
462:     adjusted.polarity -= 0.05;
463:     adjusted.altitude -= 0.05;
464:   }
465: 
466:   // Floor clamp: no dimension weight should go below 0.01
467:   adjusted.altitude = Math.max(0.01, adjusted.altitude);
468:   adjusted.driveHealth = Math.max(0.01, adjusted.driveHealth);
469:   adjusted.polarity = Math.max(0.01, adjusted.polarity);
470:   adjusted.shadowTopology = Math.max(0.01, adjusted.shadowTopology);
471:   adjusted.transformationReadiness = Math.max(0.01, adjusted.transformationReadiness);
472: 
473:   // Normalise to sum to 1.0
474:   const total = adjusted.altitude + adjusted.driveHealth + adjusted.polarity
475:     + adjusted.shadowTopology + adjusted.transformationReadiness;
476: 
477:   if (total <= 0) {
478:     // Safety: if adjustments produced all-zero/negative, return defaults
479:     return { ...DEFAULT_CCI_WEIGHTS };
480:   }
481: 
482:   return {
483:     altitude: adjusted.altitude / total,
484:     driveHealth: adjusted.driveHealth / total,
485:     polarity: adjusted.polarity / total,
486:     shadowTopology: adjusted.shadowTopology / total,
487:     transformationReadiness: adjusted.transformationReadiness / total,
488:   };
489: }
