491: // ---------------------------------------------------------------------------
492: // Session signal derivation
493: // ---------------------------------------------------------------------------
494: 
495: /**
496:  * Select the recommended session theme based on dimensional analysis.
497:  * Priority-ordered: active transformation > post-transformation > critical shadow >
498:  * severe fixation > imminent transformation > polarity momentum > growth-edge >
499:  * consolidation > balanced-development.
500:  */
501: export function selectSessionTheme(
502:   dimensions: Record<string, number>,
503:   inputs: CCIDimensionInputs,
504: ): SessionTheme {
505:   // Active transformation overrides all
506:   if (inputs.transformationReadiness.pendingTransformation) return 'active-transformation';
507: 
508:   // Post-transformation recovery (first 5 sessions after transition)
509:   if (inputs.transformationReadiness.sessionsSinceLastTransformation < 5) return 'post-transformation';
510: 
511:   // Critical shadow pressure demands attention
512:   if (inputs.shadowTopology.maxSeverity > 0.8 || inputs.shadowTopology.compoundPatternCount >= 3) {
513:     return 'shadow-integration';
514:   }
515: 
516:   // Severe drive fixation demands rebalancing
517:   if (inputs.driveHealth.maxFixationRisk > 0.7) return 'drive-rebalancing';
518: 
519:   // Imminent transformation: prep mode
520:   if (inputs.transformationReadiness.linesAtEdge >= 5 && inputs.transformationReadiness.catalystSaturation > 0.7) {
521:     return 'transformation-prep';
522:   }
523: 
524:   // High polarity momentum: deepen
525:   if (inputs.polarity.crystallizationIndex > 0.7 && inputs.polarity.masterMode === 'crystallizing') {
526:     return 'polarity-deepening';
527:   }
528: 
529:   // High altitude with low spread: push the growth edge
530:   if (dimensions['altitude'] > 0.5 && inputs.altitude.spread < 0.15) {
531:     return 'growth-edge-push';
532:   }
533: 
534:   // High altitude with high spread: consolidate
535:   if (dimensions['altitude'] > 0.5 && inputs.altitude.spread > 0.25) {
536:     return 'consolidation';
537:   }
538: 
539:   return 'balanced-development';
540: }
541: 
542: /**
543:  * Compute intensity budget: how much intensity the session can sustain.
544:  * Capped by the weakest link (drive health or shadow state) with a base
545:  * boost from altitude.
546:  */
547: export function computeIntensityBudget(dimensions: Record<string, number>): number {
548:   const healthFloor = Math.min(
549:     dimensions['driveHealth'] ?? 1,
550:     dimensions['shadowTopology'] ?? 1,
551:   );
552:   const altitudeFactor = 0.4 + ((dimensions['altitude'] ?? 0) * 0.3);
553:   return clamp(healthFloor * 0.6 + altitudeFactor * 0.4);
554: }
555: 
556: /**
557:  * Classify shadow pressure level from topology input thresholds.
558:  */
559: export function classifyShadowPressure(input: ShadowTopologyInput): ShadowPressureLevel {
560:   if (input.maxSeverity > 0.8 || input.compoundPatternCount >= 3) return 'critical';
561:   if (input.unresolvedCount > 6 || input.maxSeverity > 0.5) return 'high';
562:   if (input.unresolvedCount > 3 || input.averageSeverity > 0.3) return 'moderate';
563:   return 'low';
564: }
565: 
566: /**
567:  * Classify transformation proximity from readiness input.
568:  */
569: export function classifyTransformationProximity(input: TransformationReadinessInput): TransformationProximity {
570:   if (input.pendingTransformation) return 'active';
571:   if (input.linesAtEdge >= 5 && input.catalystSaturation > 0.7) return 'imminent';
572:   if (input.linesAtEdge >= 3) return 'approaching';
573:   return 'distant';
574: }
575: 
576: /**
577:  * Identify which drive most needs rebalancing exercise.
578:  * Returns the COMPLEMENT of the most imbalanced/fixated drive.
579:  */
580: export function identifyRebalancingTarget(input: DriveHealthInput): Drive | null {
581:   const candidates = ALL_DRIVES
582:     .filter(d => Math.abs(input.balance[d]) > 0.4 || input.fixationRisk[d] > 0.5)
583:     .sort((a, b) => input.fixationRisk[b] - input.fixationRisk[a]);
584: 
585:   if (candidates.length === 0) return null;
586: 
587:   // Return the COMPLEMENT of the over-expressed/fixated drive
588:   const overExpressed = candidates[0];
589:   const complementMap: Record<Drive, Drive> = {
590:     'Agency': 'Communion',
591:     'Communion': 'Agency',
592:     'Eros': 'Agape',
593:     'Agape': 'Eros',
594:   };
595:   return complementMap[overExpressed];
596: }
597: 
598: /**
599:  * Derive polarity session guidance based on master polarity mode.
600:  * Controls diversity of polarity textures and temptation (counter-polarity)
601:  * challenge frequency within the session.
602:  */
603: export function derivePolarityGuidance(input: PolarityInput): PolaritySessionGuidance {
604:   switch (input.masterMode) {
605:     case 'exploration':
606:       return {
607:         mode: 'exploration',
608:         recommendedDiversity: 0.9,
609:         temptationFrequency: 0.0,
610:       };
611:     case 'crystallizing':
612:       return {
613:         mode: 'crystallizing',
614:         recommendedDiversity: 0.4,
615:         temptationFrequency: 0.15 + (0.35 * input.crystallizationIndex),
616:       };
617:     case 'crystallized':
618:       return {
619:         mode: 'crystallized',
620:         recommendedDiversity: 0.2,
621:         temptationFrequency: 0.1,
622:       };
623:   }
624: }
625: 
626: /**
627:  * Derive all session signals from normalised dimensions and raw inputs.
628:  */
629: function deriveSessionSignals(
630:   dimensions: Record<string, number>,
631:   inputs: CCIDimensionInputs,
632: ): CCISessionSignals {
633:   const recommendedTheme = selectSessionTheme(dimensions, inputs);
634:   const intensityBudget = computeIntensityBudget(dimensions);
635:   const shadowPressure = classifyShadowPressure(inputs.shadowTopology);
636:   const transformationProximity = classifyTransformationProximity(inputs.transformationReadiness);
637:   const driveRebalancingTarget = identifyRebalancingTarget(inputs.driveHealth);
638:   const polarityGuidance = derivePolarityGuidance(inputs.polarity);
639: 
640:   return {
641:     recommendedTheme,
642:     intensityBudget,
643:     shadowPressure,
644:     transformationProximity,
645:     driveRebalancingTarget,
646:     polarityGuidance,
647:   };
648: }
649: 
650: // ---------------------------------------------------------------------------
651: // Main entry point
652: // ---------------------------------------------------------------------------
653: 
654: /**
655:  * Compute the Cumulative Consciousness Index from a SignificatorSnapshot.
656:  *
657:  * Pure function: same input always produces same output. No side effects.
658:  * All dimensions are normalised to [0.0, 1.0]. Weights always sum to 1.0.
659:  */
660: export function computeCCI(snapshot: SignificatorSnapshot): CCIScore {
661:   // 1. Extract inputs from Significator snapshot
662:   const inputs = extractDimensionInputs(snapshot);
663: 
664:   // 2. Normalise each dimension to [0, 1]
665:   const dimensions = {
666:     altitude: normaliseAltitude(inputs.altitude),
667:     driveHealth: normaliseDriveHealth(inputs.driveHealth),
668:     polarity: normalisePolarity(inputs.polarity),
669:     shadowTopology: normaliseShadowTopology(inputs.shadowTopology),
670:     transformationReadiness: normaliseTransformationReadiness(inputs.transformationReadiness),
671:   };
672: 
673:   // 3. Adjust weights based on state
674:   const weights = adjustWeights(DEFAULT_CCI_WEIGHTS, inputs);
675: 
676:   // 4. Compute weighted composite
677:   const composite = clamp(
678:     dimensions.altitude * weights.altitude +
679:     dimensions.driveHealth * weights.driveHealth +
680:     dimensions.polarity * weights.polarity +
681:     dimensions.shadowTopology * weights.shadowTopology +
682:     dimensions.transformationReadiness * weights.transformationReadiness
683:   );
684: 
685:   // 5. Identify dominant dimension (highest weighted contribution)
686:   const contributions: { key: keyof CCIWeights; value: number }[] = [
687:     { key: 'altitude', value: dimensions.altitude * weights.altitude },
688:     { key: 'driveHealth', value: dimensions.driveHealth * weights.driveHealth },
689:     { key: 'polarity', value: dimensions.polarity * weights.polarity },
690:     { key: 'shadowTopology', value: dimensions.shadowTopology * weights.shadowTopology },
691:     { key: 'transformationReadiness', value: dimensions.transformationReadiness * weights.transformationReadiness },
692:   ];
693:   contributions.sort((a, b) => b.value - a.value);
694:   const dominantDimension = contributions[0].key;
695: 
696:   // 6. Derive session signals
697:   const sessionSignals = deriveSessionSignals(dimensions, inputs);
698: 
699:   return { composite, dimensions, weights, dominantDimension, sessionSignals };
700: }
